await (async(p)=>{const body=async()=>{let s='';for(const f of p.frames())s+='\n'+await f.locator('body').innerText().catch(()=>'');return s}; const click=async(fn)=>{for(let n=0;n<70;n++){for(const f of p.frames()){const l=fn(f);if(await l.isVisible().catch(()=>false)){await l.click();return}}await p.waitForTimeout(250)}throw Error('Expected native UI control not available')}; await click(f=>f.locator('[title="Settings"],[title="Stillingar"]').first()); await p.waitForTimeout(500);await click(f=>f.getByText(/^(My Settings|Mínar stillingar)$/).first());await p.waitForTimeout(800);await click(f=>f.locator('[aria-label="Review or update the value for Language"],[aria-label*="Language"][role="button"],[aria-label*="Tungumál"][role="button"]').first());await p.waitForTimeout(1000);for(const f of p.frames()){const l=f.locator('[title^="Search"],[title^="Leita"]').last();if(/Available Languages|Tiltæk tungumál/.test(await f.locator('body').innerText().catch(()=>''))&&await l.isVisible().catch(()=>false)){await l.click();break}}await p.waitForTimeout(600);let filled=false;for(const f of p.frames()){const l=f.locator('[aria-label="Search Available Languages"],[aria-label*="Leita"][type="search"]');if(await l.isVisible().catch(()=>false)){await l.fill("English (United States)");filled=true;break}}if(!filled)throw Error('Language lookup search unavailable');await p.waitForTimeout(1200);let selected=false;for(const f of p.frames()){const row=f.getByRole('row').filter({hasText:"English (United States)"}).last();if(await row.isVisible().catch(()=>false)){await row.dblclick();selected=true;break}}if(!selected)throw Error('Requested language row unavailable');await p.waitForTimeout(700);await click(f=>f.getByText(/^(OK|Í lagi)$/).last());await p.waitForTimeout(5000);return {languageSelected:"English (United States)"};})(page);
